package io.algora.interpreter;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import static io.algora.interpreter.Program.*;
/** One execution on a virtual thread. Debug controls never depend on JavaFX. */
public final class DebugSession {
 private static final class Cell {Object value;final String type;final List<int[]> ranges;final boolean constant;Cell(Object v,String t,List<int[]> r,boolean c){value=v;type=t;ranges=r;constant=c;}}
 private record Reference(Cell cell,List<Integer> indices){}
 private static final class Break extends RuntimeException{}
 private static final class Return extends RuntimeException{final Object value;Return(Object v){value=v;}}
 private final Program program;private final InputProvider input;private final Consumer<String> output;private final Consumer<Snapshot> observer;
 private final List<Map<String,Cell>> scopes=new ArrayList<>();private final Object monitor=new Object();private volatile Set<Integer> breakpoints=Set.of();private volatile boolean stopped,single,started;private volatile Thread worker;private volatile Status status=Status.READY;private volatile Snapshot latest=new Snapshot(0,Map.of(),Status.READY,0);private int line,depth;private long steps,maxSteps=100_000;private int maxDepth=100;private boolean echo=true;private double[] randomInput;private DoubleSupplier random=Math::random;
 DebugSession(Program p,InputProvider in,Consumer<String> out,Consumer<Snapshot> obs){program=p;input=in;output=out==null?s->{}:out;observer=obs==null?s->{}:obs;scopes.add(new LinkedHashMap<>());declare(p.declarations(),scopes.getFirst());publish();}
 public DebugSession limits(long instructions,int calls){if(started)throw new IllegalStateException("Execução iniciada");if(instructions<1||calls<1)throw new IllegalArgumentException("Limites devem ser positivos");maxSteps=instructions;maxDepth=calls;return this;}
 public DebugSession random(DoubleSupplier generator){if(started)throw new IllegalStateException("Execução iniciada");random=Objects.requireNonNull(generator);return this;}
 public synchronized CompletableFuture<Snapshot> start(boolean debug){if(started)throw new IllegalStateException("Crie uma nova sessão para reiniciar");started=true;single=debug;CompletableFuture<Snapshot> result=new CompletableFuture<>();worker=Thread.ofVirtual().name("algora-interpreter").unstarted(()->{status=Status.RUNNING;try{block(program.body());check();status=Status.COMPLETED;publish();result.complete(latest);}catch(CancellationException e){status=Status.STOPPED;publish();result.complete(latest);}catch(Throwable e){status=Status.ERROR;publish();if(e instanceof Break)e=error("interrompa fora de um laço");if(e instanceof Return)e=error("retorne fora de uma função");result.completeExceptionally(e);}});worker.start();return result;}
 public void setBreakpoints(Set<Integer> lines){breakpoints=Set.copyOf(lines);}
 public void step(){synchronized(monitor){single=true;status=Status.RUNNING;monitor.notifyAll();}}
 public void resume(){synchronized(monitor){single=false;status=Status.RUNNING;monitor.notifyAll();}}
 public void pause(){single=true;}
 public void stop(){stopped=true;synchronized(monitor){monitor.notifyAll();}Thread thread=worker;if(thread!=null)thread.interrupt();}
 public Snapshot snapshot(){return latest;}
 private AlgoraException error(String message){return new AlgoraException(line,message);}
 private void check(){if(stopped||Thread.currentThread().isInterrupted())throw new CancellationException("Execução interrompida");if(steps>maxSteps)throw error("Limite de instruções excedido");}
 private void checkpoint(int currentLine){line=currentLine;steps++;check();if(single||breakpoints.contains(line)){synchronized(monitor){status=Status.PAUSED;publish();while(status==Status.PAUSED&&!stopped)try{monitor.wait();}catch(InterruptedException e){Thread.currentThread().interrupt();throw new CancellationException();}}check();}status=Status.RUNNING;publish();}
 private Object copy(Object value){if(value instanceof List<?> list)return list.stream().map(this::copy).toList();return value;}
 private void publish(){Map<String,Object> vars=new LinkedHashMap<>();if(!scopes.isEmpty()){for(var e:scopes.getFirst().entrySet())vars.put(e.getKey(),copy(e.getValue().value));for(var e:scopes.getLast().entrySet())vars.put(e.getKey(),copy(e.getValue().value));}latest=new Snapshot(line,Collections.unmodifiableMap(vars),status,steps);observer.accept(latest);}
 private long slots(List<int[]> ranges){long size=1,total=1;for(var r:ranges){size=Math.multiplyExact(size,(long)r[1]-r[0]+1);total=Math.addExact(total,size);}return total;}
 private void declare(List<Declaration> declarations,Map<String,Cell> scope){long allocated=0;for(var current:scopes)for(var cell:current.values())allocated+=slots(cell.ranges);for(var d:declarations){if(scope.containsKey(d.name()))throw error("Variável duplicada: "+d.name());List<int[]> ranges=new ArrayList<>();for(var range:d.ranges()){double low=num(eval(range.get(0))),high=num(eval(range.get(1)));if(low!=Math.rint(low)||high!=Math.rint(high)||low<Integer.MIN_VALUE||high>Integer.MAX_VALUE||high<low)throw error("Limites de vetor inválidos");ranges.add(new int[]{(int)low,(int)high});}try{allocated+=slots(ranges);}catch(ArithmeticException e){throw error("Vetor excede limite de memória");}if(allocated>1_000_000)throw error("Vetor excede limite de memória");Object value=d.constant()!=null?eval(d.constant()):initial(d.type(),ranges,0);scope.put(d.name(),new Cell(value,d.type(),List.copyOf(ranges),d.constant()!=null));}}
 private Object initial(String type,List<int[]> ranges,int dimension){if(dimension==ranges.size())return switch(type){case "inteiro","real"->0.0;case "logico"->false;default->"";};List<Object> values=new ArrayList<>();int[] r=ranges.get(dimension);for(long i=r[0];i<=r[1];i++)values.add(initial(type,ranges,dimension+1));return values;}
 private Cell cell(String name){Cell cell=scopes.getLast().get(name);if(cell==null)cell=scopes.getFirst().get(name);if(cell==null)throw error("Variável não declarada: "+name);return cell;}
 private boolean bound(String name){return scopes.getLast().containsKey(name)||scopes.getFirst().containsKey(name);}
 private Reference reference(Expression expr){if(!expr.kind().equals("reference"))throw error("Variável esperada");Cell cell=cell((String)expr.value());if(expr.children().size()!=cell.ranges.size())throw error("Dimensões inválidas: "+expr.value());List<Integer> indices=new ArrayList<>();for(int i=0;i<expr.children().size();i++){double n=num(eval(expr.children().get(i)));int[] range=cell.ranges.get(i);if(n!=Math.rint(n)||n<range[0]||n>range[1])throw error("Índice fora dos limites: "+n);indices.add((int)n-range[0]);}return new Reference(cell,indices);}
 @SuppressWarnings("unchecked") private Object get(Expression expr){var ref=reference(expr);Object value=ref.cell.value;for(int i:ref.indices)value=((List<Object>)value).get(i);return value;}
 private double num(Object value){try{double n=value instanceof Number number?number.doubleValue():Double.parseDouble(String.valueOf(value));if(!Double.isFinite(n))throw error("Valor numérico inválido");return n;}catch(NumberFormatException e){throw error("Valor numérico inválido: "+value);}}
 private boolean truth(Object value){if(value instanceof Boolean b)return b;throw error("Condição deve ser lógica");}
 private String text(Object value){if(value instanceof Boolean b)return b?"VERDADEIRO":"FALSO";if(value instanceof Double d&&d==Math.rint(d))return String.format(Locale.ROOT,"%.0f",d);return String.valueOf(value);}
 private Object convert(Object value,String type){return switch(type){case "real"->num(value);case "inteiro"->{double n=num(value);yield n<0?Math.ceil(n):Math.floor(n);}case "logico"->{if(value instanceof Boolean)yield value;String s=String.valueOf(value).toLowerCase(Locale.ROOT);if(s.equals("verdadeiro"))yield true;if(s.equals("falso"))yield false;throw error("Valor lógico inválido");}default->text(value);};}
 @SuppressWarnings("unchecked") private void set(Expression expr,Object value){var ref=reference(expr);if(ref.cell.constant)throw error("Não é permitido alterar uma constante");value=convert(value,ref.cell.type);if(ref.indices.isEmpty())ref.cell.value=value;else{List<Object> values=(List<Object>)ref.cell.value;for(int i:ref.indices.subList(0,ref.indices.size()-1))values=(List<Object>)values.get(i);values.set(ref.indices.getLast(),value);}}
 private boolean equal(Object a,Object b){if(a instanceof Number&&b instanceof Number)return Double.compare(num(a),num(b))==0;return Objects.equals(a,b);}
 private int compare(Object a,Object b){if(a instanceof Number&&b instanceof Number)return Double.compare(num(a),num(b));if(a instanceof String&&b instanceof String)return ((String)a).compareTo((String)b);throw error("Comparação entre tipos incompatíveis");}
 private Object eval(Expression expr){check();return switch(expr.kind()){case "literal"->expr.value();case "reference"->{String name=(String)expr.value();if(!bound(name)&&expr.children().isEmpty()&&(name.equals("pi")||name.equals("rand")))yield call(name,List.of());yield get(expr);}case "call"->call((String)expr.value(),expr.children());case "unary"->{Object value=eval(expr.children().getFirst());yield switch((String)expr.value()){case "nao"->!truth(value);case "-"->-num(value);default->num(value);};}case "binary"->binary(expr);default->throw error("Expressão inválida");};}
 private Object binary(Expression expr){String op=(String)expr.value();Object a=eval(expr.children().getFirst());if(op.equals("e")&&!truth(a))return false;if(op.equals("ou")&&truth(a))return true;Object b=eval(expr.children().getLast());Object result=switch(op){case "+"->a instanceof String||b instanceof String?text(a)+text(b):num(a)+num(b);case "-"->num(a)-num(b);case "*"->num(a)*num(b);case "/","\\","div","%","mod"->{if(num(b)==0)throw error("Divisão por zero");double n=num(a)/num(b);yield op.equals("/")?n:op.equals("%")||op.equals("mod")?num(a)%num(b):n<0?Math.ceil(n):Math.floor(n);}case "^"->Math.pow(num(a),num(b));case "="->equal(a,b);case "!=","<>"->!equal(a,b);case "<"->compare(a,b)<0;case ">"->compare(a,b)>0;case "<="->compare(a,b)<=0;case ">="->compare(a,b)>=0;case "e"->truth(a)&&truth(b);case "ou"->truth(a)||truth(b);case "xou"->truth(a)!=truth(b);default->throw error("Operador inválido");};if(result instanceof Double n&&!Double.isFinite(n))throw error("Resultado numérico inválido");return result;}
 private double random(){double n=random.getAsDouble();if(!Double.isFinite(n)||n<0||n>=1)throw error("Gerador aleatório deve retornar valor em [0,1)");return n;}
 private Object call(String name,List<Expression> args){Set<String> zero=Set.of("pi","rand");Set<String> one=Set.of("abs","raizq","quad","int","sen","cos","tan","arctan","arccos","arcsen","cotan","grauprad","radpgrau","log","logn","compr","maiusc","minusc","asc","carac","numpcarac","caracpnum","randi");Set<String> two=Set.of("exp","pos");boolean builtin=zero.contains(name)||one.contains(name)||two.contains(name)||name.equals("copia");if(builtin){int arity=zero.contains(name)?0:one.contains(name)?1:two.contains(name)?2:3;if(args.size()!=arity)throw error("Quantidade de argumentos inválida: "+name);List<Object> values=new ArrayList<>();for(var a:args)values.add(eval(a));Object a=values.isEmpty()?0.0:values.getFirst();Object result=switch(name){case "pi"->Math.PI;case "rand"->random();case "abs"->Math.abs(num(a));case "raizq"->Math.sqrt(num(a));case "quad"->num(a)*num(a);case "int"->num(a)<0?Math.ceil(num(a)):Math.floor(num(a));case "sen"->Math.sin(num(a));case "cos"->Math.cos(num(a));case "tan"->Math.tan(num(a));case "arctan"->Math.atan(num(a));case "arccos"->Math.acos(num(a));case "arcsen"->Math.asin(num(a));case "cotan"->1/Math.tan(num(a));case "grauprad"->Math.toRadians(num(a));case "radpgrau"->Math.toDegrees(num(a));case "exp"->Math.pow(num(a),num(values.get(1)));case "log"->Math.log10(num(a));case "logn"->Math.log(num(a));case "compr"->(double)text(a).length();case "maiusc"->text(a).toUpperCase(Locale.ROOT);case "minusc"->text(a).toLowerCase(Locale.ROOT);case "asc"->{if(text(a).isEmpty())throw error("asc requer texto não vazio");yield (double)text(a).charAt(0);}case "carac"->String.valueOf((char)(int)num(a));case "numpcarac"->text(a);case "caracpnum"->num(a);case "pos"->(double)(text(values.get(1)).indexOf(text(a))+1);case "copia"->{String s=text(a);int start=(int)num(values.get(1))-1,count=(int)num(values.get(2));if(start<0||count<0)throw error("Índices de copia inválidos");yield start>=s.length()?"":s.substring(start,Math.min(s.length(),start+count));}case "randi"->{double n=num(a);if(n<=0||n!=Math.rint(n))throw error("randi requer limite inteiro positivo");yield Math.floor(random()*n);}default->throw error("Função inválida");};if(result instanceof Double n&&!Double.isFinite(n))throw error("Resultado inválido: "+name);return result;}
 Routine routine=program.routines().stream().filter(r->r.name().equals(name)).findFirst().orElseThrow(()->error("Função/procedimento desconhecido: "+name));if(routine.parameters().size()!=args.size())throw error("Quantidade de argumentos inválida: "+name);if(depth>=maxDepth)throw error("Limite de chamadas excedido");Map<String,Cell> local=new LinkedHashMap<>();for(int i=0;i<args.size();i++){Parameter p=routine.parameters().get(i);if(p.reference()){var ref=reference(args.get(i));if(!ref.indices.isEmpty())throw error("Referência requer variável escalar");local.put(p.name(),ref.cell);}else local.put(p.name(),new Cell(convert(eval(args.get(i)),p.type()),p.type(),List.of(),false));}scopes.add(local);depth++;try{declare(routine.declarations(),local);block(routine.body());return 0.0;}catch(Return r){return r.value;}finally{scopes.removeLast();depth--;}}
 private void block(List<Statement> statements){for(var statement:statements)execute(statement);}
 private void execute(Statement s){checkpoint(s.line());switch(s.kind()){
 case "assign"->set(s.field("target"),eval(s.field("value")));
 case "call"->eval(s.field("value"));
 case "write","writeln"->{StringBuilder text=new StringBuilder();for(Output arg:s.<List<Output>>field("values")){Object value=eval(arg.value());String part=arg.precision()==null?text(value):String.format(Locale.ROOT,"%."+Math.max(0,Math.min(100,(int)num(eval(arg.precision()))))+"f",num(value));if(arg.width()!=null){int width=Math.max(0,Math.min(10000,(int)num(eval(arg.width()))));part=" ".repeat(Math.max(0,width-part.length()))+part;}text.append(part);}if(s.kind().equals("writeln"))text.append('\n');output.accept(text.toString());}
 case "read"->{for(Expression target:s.<List<Expression>>field("targets")){String value;if(randomInput!=null){var ref=reference(target);if(!Set.of("inteiro","real").contains(ref.cell.type))throw error("Entrada aleatória implementada apenas para números");double scale=ref.cell.type.equals("inteiro")?1:Math.pow(10,randomInput[2]);double low=Math.ceil(randomInput[0]*scale),high=Math.floor(randomInput[1]*scale);if(high<low)throw error("Intervalo aleatório sem valores representáveis");value=text((low+Math.floor(random()*(high-low+1)))/scale);if(echo)output.accept(value+"\n");}else{if(input==null)throw error("Entrada não disponível");try{value=input.read();}catch(InterruptedException e){Thread.currentThread().interrupt();throw new CancellationException();}catch(Exception e){throw error("Falha na leitura: "+e.getMessage());}if(value==null)throw error("Entrada encerrada");}check();set(target,value);}}
 case "if"->block(truth(eval(s.field("condition")))?s.field("yes"):s.field("no"));
 case "while"->{try{while(truth(eval(s.field("condition")))){block(s.field("body"));checkpoint(s.line());}}catch(Break ignored){}}
 case "repeat"->{try{do{block(s.field("body"));checkpoint(s.line());}while(!truth(eval(s.field("condition"))));}catch(Break ignored){}}
 case "for"->{double from=num(eval(s.field("from"))),to=num(eval(s.field("to"))),step=num(eval(s.field("step")));if(step==0)throw error("Passo inválido");Expression target=new Expression("reference",s.field("name"),List.of());try{for(double n=from;step>0?n<=to:n>=to;n+=step){set(target,n);block(s.field("body"));checkpoint(s.line());}}catch(Break ignored){}}
 case "choice"->{Object value=eval(s.field("value"));List<Statement> body=s.field("otherwise");outer:for(Case branch:s.<List<Case>>field("cases"))for(var item:branch.values()){Object from=eval(item.from());if(item.to()==null?equal(value,from):compare(value,from)>=0&&compare(value,eval(item.to()))<=0){body=branch.body();break outer;}}block(body);}
 case "return"->throw new Return(eval(s.field("value")));
 case "break"->throw new Break();
 case "clear"->output.accept("\u001b[2J\u001b[H");
 case "echo"->echo=s.field("enabled");
 case "random"->{if(!s.<Boolean>field("enabled")){randomInput=null;break;}List<Expression> args=s.field("args");double low=args.isEmpty()?0:num(eval(args.get(0))),high=args.isEmpty()?100:num(eval(args.get(1))),decimals=args.size()<3?0:num(eval(args.get(2)));if(low>high||decimals<0||decimals>10||decimals!=Math.rint(decimals)||Math.max(Math.abs(low),Math.abs(high))*Math.pow(10,decimals)>9_007_199_254_740_991.0)throw error("Configuração aleatória inválida");randomInput=new double[]{low,high,decimals};}
 case "noop"->{}
 default->throw error("Comando desconhecido: "+s.kind());}}
}
